static Phases Stages(params StatusKind[] status)
{
    Phases stages = new Phases { Compact = true };
    string[] names = { "Fetch", "Build", "Test", "Pack", "Publish" };
    for (int i = 0; i < names.Length; i++)
    {
        stages.Set(names[i], status[i]);
    }
    return stages;
}

